import { Directive, input, signal } from '@angular/core';
import { ControlValueAccessor } from '@angular/forms';

@Directive()
export abstract class BaseInput<T = any> implements ControlValueAccessor {

  label = input<string>('');
  placeholder = input<string>('');
  hint = input<string>('');
  required = input<boolean>(false);


  value = signal<T | null>(null);
  disabled = signal<boolean>(false);


  protected onChange: (value: T | null) => void = () => { };
  protected onTouched: () => void = () => { };


  handleInput(event: Event): void {
    const target = event.target as HTMLInputElement;
    const val = this.convertToValue(target.value);
    this.value.set(val);
    this.onChange(val);
  }

  handleBlur(): void {
    this.onTouched();
  }


  protected abstract convertToValue(value: string): T | null;


  writeValue(value: T): void {
    this.value.set(value);
  }

  registerOnChange(fn: any): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabled.set(isDisabled);
  }
}

import { Directive, ElementRef, HostListener, inject, input } from '@angular/core';

export const numberFilterExp = /^\-?\d*\.{1}?\d*$/;
export const integerFilterExp = /^\-?\d*$/;

@Directive({
  selector: '[vnFilterNumber]',
  standalone: true
})
export class FilterNumberDirective {
  private el = inject(ElementRef);
  isInteger = input<boolean>(false);

  @HostListener('keydown', ['$event'])
  onKeyDown(event: KeyboardEvent) {
    const allowedKeys = ['Backspace', 'Tab', 'End', 'Home', 'ArrowLeft', 'ArrowRight', 'Delete', 'Enter', 'Control'];

    const inputEl = this.el.nativeElement as HTMLInputElement;
    const currentVal = inputEl.value + event.key;

    console.log("Current Value: ", currentVal)
    const regex = this.isInteger() ? integerFilterExp : numberFilterExp;

    if (!regex.test(currentVal)) {
      event.preventDefault()

    }

    if (!allowedKeys.includes(event.key)) {
      event.preventDefault();

    }


  }
}

import { Directive, HostListener } from '@angular/core';

@Directive({
  selector: '[vnIntFilter]',
  standalone: true,
})
export class IntFilterDirective {

  @HostListener('keydown', ['$event'])
  onKeyDown(event: KeyboardEvent) {
    const allowedKeys = ['Backspace', 'Tab', 'End', 'Home', 'ArrowLeft', 'ArrowRight', 'Delete', 'Enter'];
    if (!/^[0-9]$/.test(event.key) && !allowedKeys.includes(event.key)) {
      event.preventDefault();
    }
  }
}

import { Directive, HostListener } from '@angular/core';

@Directive({
  selector: '[vnIntFilter]',
  standalone: true,
})
export class NumFilterDirective {

  @HostListener('keydown', ['$event'])
  onKeyDown(event: KeyboardEvent) {
    const allowedKeys = ['Backspace', 'Tab', 'End', 'Home', 'ArrowLeft', 'ArrowRight', 'Delete', 'Enter'];

    if (!/^[0-9]$/.test(event.key.replace('.', '0')) && !allowedKeys.includes(event.key)) {
      event.preventDefault();
    }
  }
}

